const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.info}</svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = value => new Intl.NumberFormat('en-SG', {style:'currency',currency:'SGD',currencyDisplay:'code',maximumFractionDigits:Number.isInteger(value)?0:6}).format(value);
const date = value => new Date(value * 1000).toLocaleDateString('en-SG',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Singapore'});
const who = address => identities.find(id => id.address.toLowerCase() === address?.toLowerCase())?.name || short(address || '0x0000000000');
const equal = (a,b) => a?.toLowerCase() === b?.toLowerCase();
const app = document.querySelector('#app');
const modal = document.querySelector('#modal');
const chain = new Chain(message => { const status = document.querySelector('#boot-status'); if(status)status.textContent=message; });
let view = new URLSearchParams(location.search).has('admin')?'admin':'overview', selected = null, actor = 0, filter = 'All', query = '', busy = false, toastTimer, mobileOpen = false;
let draft = null, wizardStep = 0;
const workflow=new WorkflowUI({chain,identities,esc,heading,button,money,date,openModal,who,run,getActor:()=>actor,closeModal:()=>modal.close()});
const sharedUI=new SharedUI({chain,KEY,identities,esc,button,heading,openModal,money,toast,render,getActor:()=>actor,setActor:i=>actor=i,isBusy:()=>busy,modalOpen:()=>modal.open});

const admin=new PresenterMode({enabled:view==='admin'});
