const adminUI=new AdminUI({gate:admin,chain,heading,button,esc,shared:sharedUI,controls:()=>experience.presenter(),go});
const governance=new GovernanceUI({chain,identities,esc,heading,button,money,who});
const localSync=new LocalSync({locks:navigator.locks,read:()=>localStorage.getItem(KEY),current:()=>JSON.stringify(chain.record),isShared:()=>sharedUI.connected,restore:async()=>{if(chain.ganache?.disconnect)await chain.ganache.disconnect();await chain.init();actor=Math.min(actor,identities.length-1);},onChange:()=>{if(!modal.open)render();}});
window.addEventListener('storage',event=>{if(event.key===KEY&&!sharedUI.connected)localSync.changed().catch(error=>toast(errorMessage(error),true));});

const donationFlows=new DonationFlowUI({chain,identities,esc,heading,button,money,who,icon,getActor:()=>actor});

function badge(status) { return `<span class="badge ${status.toLowerCase()}">${['Completed','Active'].includes(status)?icon('check'):icon('clock')}${status === 'Completed' ? 'Payments released' : status === 'Active' ? 'Fully funded' : status === 'Refunds' ? 'Refunds available' : status}</span>`; }
function campaignBadge(c){return badge(c.status==='Refunds'&&c.refundPool>0&&c.refundPaid>=c.refundPool?'Refunds settled':c.status);}
function button(label, action, type='primary', iconName='') { return `<button class="btn ${type}" data-action="${action}" ${busy?'disabled':''}>${iconName?icon(iconName):''}${label}</button>`; }
function toast(message, error=false) { const t = document.querySelector('#toast'); clearTimeout(toastTimer); t.textContent=message; t.className=`show ${error?'error':''}`; toastTimer=setTimeout(()=>t.className='',6500); }
function errorMessage(error) {
  let message=error?.info?.error?.data?.reason || error?.info?.error?.message || error?.reason || error?.shortMessage || error?.message || 'Something went wrong.';
  if(message.includes('revert '))message=message.split('revert ').pop();
  return message.length > 180 ? message.slice(0,180) : message;
}
async function run(message, fn, success) {
  if (busy || sharedUI.syncing) return;
  busy=true; render();
  const indicator=document.createElement('div');indicator.className='busy-banner';indicator.innerHTML=`<span class="spinner"></span>${esc(message)}`;document.body.append(indicator);
  modal.querySelectorAll('button').forEach(b=>b.disabled=true);
  try { await localSync.acquire();await sharedUI.beforeMutation(); const result=await fn(); await chain.refresh(); await sharedUI.afterMutation(); if(success)toast(success); return result; }
  catch(error){await sharedUI.failedMutation();toast(errorMessage(error),true);throw error;}
  finally {localSync.finish();busy=false;indicator.remove();modal.querySelectorAll('button').forEach(b=>b.disabled=false);render();}
}
function openModal(title, subtitle, body, footer='') {
  modal.innerHTML=`<div class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="close" data-action="close-modal" aria-label="Close dialog">${icon('x')}</button></div>${body}${footer}`;
  if(!modal.open)modal.showModal();
}
function go(next, id=null) { if(next==='presenter')next='admin';if(next==='tour'&&!admin.unlocked)next='admin';if(next==='admin')admin.open();sessionStorage.setItem('cleargive-participant-index',String(actor));if(modal.open)modal.close();view=next;selected=id;filter='All';query='';mobileOpen=false;render();window.scrollTo({top:0,behavior:'instant'}); }
function current() { return chain.campaigns.find(c=>equal(c.address,selected)); }
function render() {
  if(['presenter','tour'].includes(view)&&!admin.unlocked){view='admin';admin.open();}
  const pending = chain.campaigns.filter(c=>!c.archived&&c.status==='Active'&&c.reviewers.some(r=>equal(r,identities[actor].address))).flatMap(c=>c.milestones.filter(m=>m.hash!==ZeroHash&&!m.paid&&!(m.reviewParticipation&(1<<c.reviewers.findIndex(r=>equal(r,identities[actor].address))))&&(!m.rejected||c.rewardEnabled))).length;
  const pageTitle={overview:'Overview',campaigns:'Campaigns',approvals:'Review requests',ledger:'Transaction ledger',about:'How ClearGive works',tour:'Guided walkthrough',accounts:'Accounts',reports:'Organisation reports',governance:'Rules & responsibilities',registration:'Organisation reviews',workspaces:'Shared workspace',welcome:'Welcome',giving:'My donations',admin:'Demo controls',presenter:'Demo controls',donationflow:'Donation money flow',detail:current()?.title||'Campaign'}[view];
  app.innerHTML=`
  <aside class="sidebar ${mobileOpen?'open':''}">
    <a class="brand" href="#" data-action="nav:overview"><img src="/assets/mark.svg" alt=""><span>Clear<span>Give</span></span></a>
    <div class="nav-caption">A little kindness. A clear purpose.</div>
    <nav class="nav" aria-label="Main navigation">
      ${experience.navigation().map(([v,i,label])=>`<button class="${view===v||view==='detail'&&v==='campaigns'||view==='donationflow'&&v==='giving'?'active':''}" data-action="nav:${v}">${icon(i)}${label}${v==='approvals'&&pending?`<span class="count">${pending}</span>`:''}</button>`).join('')}
    </nav>
    <nav class="nav" aria-label="Workspace tools"><button data-action="nav:workspaces">${icon('users')}Shared workspace</button><button data-action="nav:admin">${icon('users')}Demo controls</button><button data-action="nav:governance">${icon('shield')}Rules & responsibilities</button></nav><div class="nav-caption">Separate environment</div><nav class="nav"><a class="btn ghost" href="/">Open XSGD platform ↗</a></nav><div class="nav-caption">Explore</div>
    <nav class="nav" aria-label="Learn"><button class="${view==='about'?'active':''}" data-action="nav:about">${icon('book')}How it works</button>${admin.unlocked?`<button class="${view==='tour'?'active':''}" data-action="nav:tour">${icon('play')}Guided walkthrough</button>`:''}</nav>
    <div class="sidebar-bottom"><div class="side-note">${icon('leaf')}<h4>Giving, with proof.</h4><p>Every contribution has a purpose. Every payment leaves a trail.</p><button data-action="nav:about">Meet ClearGive ${icon('arrow')}</button></div><div class="side-footer"><span>Giving, with proof.</span></div></div>
  </aside>
  <main class="main"><header class="topbar"><button class="mobile-menu" data-action="mobile-menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb">Workspace ${icon('chevron')} <strong>${esc(pageTitle.length>35&&view==='detail'?'Campaign details':pageTitle)}</strong></div><div class="top-controls"><span class="network"><span class="dot"></span>Sandbox · Virtual SGD</span><div class="role-control"><div class="avatar">${esc(identities[actor].initials)}</div>${admin.unlocked?`<select id="role-select" aria-label="Admin: demonstrate an account">${identities.map((id,i)=>`<option value="${i}" ${actor===i?'selected':''}>${esc(id.name)} · ${esc(id.role)}</option>`).join('')}</select>`:`<span class="participant-name">${esc(identities[actor].name)}</span>`}</div>${admin.unlocked?button('Participant view','admin-exit','ghost','arrow'):''}</div></header>
  <div class="content">${({overview:()=>experience.role()==='donor'?overview():experience.roleHome(),welcome:()=>experience.welcome(),giving:()=>experience.giving(),donationflow:()=>donationFlows.page(selected),admin:()=>adminUI.page(),presenter:()=>adminUI.page(),campaigns:campaignPage,detail:detailPage,approvals:approvalPage,ledger:ledgerPage,about:aboutPage,tour:tourPage,accounts:accountsPage,reports:reportsPage,governance:()=>governance.page(),registration:()=>workflow.registrationPage(),workspaces:()=>sharedUI.page()}[view]||overview)()}<footer class="footer"><span>© 2026 ClearGive. <strong>Good intentions. Clear outcomes.</strong></span><span><a href="/photo-credits.html">Photo credits</a> · <a href="/demo?admin=1">Demo controls</a></span></footer></div></main>`;
}
function heading(title, description, actions='') {return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="buttons">${actions}</div>`:''}</div>`;}
function stats() {
  const raised=chain.campaigns.reduce((n,c)=>n+c.raised,0),released=chain.campaigns.reduce((n,c)=>n+c.released,0),refund=chain.campaigns.reduce((n,c)=>n+c.refundPaid,0);
  const data=[['Total contributions',money(raised),'heart','Across every campaign'],['Held in escrow',money(raised-released-refund),'lock','Protected by contract rules'],['Paid to suppliers',money(released),'send','Two assigned account approvals per payment'],['Campaigns',chain.campaigns.length,'leaf',`${chain.campaigns.filter(c=>c.status==='Completed').length} payments complete · ${chain.campaigns.filter(c=>c.status==='Funding'||c.status==='Active').length} ongoing`]];
  return `<div class="stats">${data.map(([label,value,i,sub])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(i)}</span></div><strong>${value}</strong><small>${i==='send'?'<span class="accent">2 of 2 reviewers</span> · ':''}${sub}</small></div>`).join('')}</div>`;
}
function campaignDescription(c){return String(c.description||'A community campaign with fixed supplier budgets and two reviewer accounts.').replaceAll('an approved supplier','the agreed supplier').replaceAll('independently reviewed quotations','quotations checked by reviewer accounts');}
function heroArt(){return `<div class="hero-art community-art"><img src="/assets/community.jpg" alt="Volunteers preparing donated goods; representative photograph"></div>`;}
const business = (id,i) => id.kind==='business'||[2,5,6,7].includes(i);
const recipientOptions = () => identities.filter((id,i)=>business(id,i)&&!equal(id.address,chain.accounts[draft?.owner??2]));
function walletName(a){if(equal(a,'0x0000000000000000000000000000000000000000'))return 'Balance added';if(equal(a,'0x000000000000000000000000000000000000dEaD'))return 'Balance adjustment';if(equal(a,chain.record.deployments.feeVault))return 'Platform fee vault';const campaign=chain.campaigns.find(c=>equal(c.address,a));return campaign?campaign.title+' · escrow':who(a);}
function accountsPage(){const id=identities[actor],history=chain.walletHistory.filter(t=>equal(t.from,id.address)||equal(t.to,id.address)),creditEvents=chain.audit.filter(e=>['ReviewerCreditsAwarded','ReviewerCreditsSpent','ReviewerCreditsRestored'].includes(e.name)&&equal(e.args.reviewer,id.address));return `${heading('A small gift starts here.','Manage your wallet and follow your contributions from giving to impact.',button('Create an account','new-account','primary','plus'))}<div class="sandbox-note">${icon('leaf')}<div><strong>Your giving, all in one place.</strong> See your available balance, contributions and payment history.</div></div><div class="wallet-layout"><section class="wallet-card"><span class="eyebrow">${business(id,actor)?'Organisation':'Personal'} account</span><h2>${esc(id.name)}</h2><span>Available wallet balance</span><strong class="wallet-total">${money(chain.balances[actor])}</strong><div class="balance-row"><span>Donation-only reviewer credits</span><strong>${money(chain.reviewerCredits[actor]||0)}</strong></div><p>Your donation stays in escrow until the campaign’s conditions are met. Payments and refunds go to the designated wallet.</p><div class="buttons">${experience.role()==='donor'?button('My donations','nav:giving','lime','heart'):button('My work','nav:overview','lime','file')}${button('Find a cause','nav:campaigns','','heart')}</div><details><summary>View wallet address</summary><p class="hash">${id.address}</p></details></section><section class="panel"><h2>Your next step</h2><p class="section-copy">Manage your giving and follow the progress of your projects.</p><div class="buttons">${button('My work','nav:overview','primary','grid')}${button('Explore campaigns','nav:campaigns','','heart')}</div></section></div><section class="panel"><h2>Your donation-credit trail</h2><p>Credits are separate from your wallet and cannot be withdrawn or transferred. Refunds of credit-funded principal restore credits.</p>${creditEvents.length?creditEvents.map(e=>`<div class="balance-row"><span>${e.name==='ReviewerCreditsAwarded'?'Earned':e.name==='ReviewerCreditsSpent'?'Spent including fee':'Refund restored'} · ${esc(e.title)}</span><strong>${money(dollars(BigInt(e.args.total||e.args.amount)))}</strong>${button('Proof',`tx:${e.hash}`,'ghost','receipt')}</div>`).join(''):'<p>No credit transactions yet.</p>'}</section><section class="panel"><div class="panel-header"><h2>${esc(id.name)}’s wallet money trail</h2><span class="badge">${history.length} transactions</span></div><div class="table-wrap"><table><thead><tr><th>From</th><th>To</th><th>Amount</th><th>Proof</th></tr></thead><tbody>${history.map(t=>`<tr><td>${esc(walletName(t.from))}</td><td>${esc(walletName(t.to))}</td><td>${equal(t.to,id.address)?'+':'−'} ${money(t.amount)}</td><td><button class="btn ghost" data-action="tx:${t.hash}">Block ${t.block} ↗</button></td></tr>`).join('')}</tbody></table>${!history.length?'<p>No transactions for this account yet.</p>':''}</div></section>`;}
function newAccount(kind='personal'){openModal('Make room for someone new.','Open an account. Your wallet is prepared automatically.',`<form id="account-form"><div class="modal-body"><div class="field"><label for="account-name">Account name</label><input id="account-name" name="name" minlength="2" maxlength="60" placeholder="e.g. Jamie Tan or Neighbourhood Kitchen" required></div><div class="field"><label for="account-kind">Account type</label><select id="account-kind" name="kind"><option value="personal" ${kind==='personal'?'selected':''}>Personal · donate and follow a cause</option><option value="business" ${kind==='business'?'selected':''}>Organisation · organise projects or supply goods</option><option value="reviewer">Reviewer · assess registrations and campaign evidence</option></select></div><div class="notice">Your account opens with SGD 0. Creating an account does not verify an organisation’s charity status. An admin allocates virtual scenario funds separately.</div><p class="inline-error" id="form-error"></p></div><div class="modal-footer"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary">Create account</button></div></form>`);}
function balanceForm(i){openModal('Adjust your wallet balance.',identities[i].name,`<form id="balance-form" data-account="${i}"><div class="modal-body"><div class="field"><label for="balance-value">Available balance (SGD)</label><input id="balance-value" name="value" type="number" min="0" max="1000000" step="0.01" value="${chain.balances[i]}" required></div><div class="notice">Adjust the available balance for a scenario. Each change is recorded. Funds committed to campaign escrow and past payments cannot be changed here.</div><p class="inline-error" id="form-error"></p></div><div class="modal-footer"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">Update balance</button></div></form>`);}
function reportsPage(){const rows=chain.campaigns.filter(c=>equal(c.organiser,chain.accounts[actor]));return `${heading('Good work. Clearly accounted for.','Project reporting for the selected organiser: '+esc(identities[actor].name),button('Export full report','export','','download'))}<div class="notice">Track budgets, approvals, payments and remaining funds for the selected organiser. Fees are separate from escrow: 60% operations reserve, 40% reviewer-credit reserve. Operations funds are held in reserve; no individual reviewer credits are awarded yet. Earlier campaigns retain their zero-fee history.</div>${rows.length?rows.map(c=>`<section class="panel project-report"><div class="panel-header"><div><span class="eyebrow">${esc(c.location)}</span><h2>${esc(c.title)}</h2></div>${button('Open project',`campaign:${c.address}`,'','arrow')}</div><div class="report-numbers">${[['Agreed budget',c.target],['Contributions',c.raised],['Platform fees'+(c.legacy?' · historical zero-fee':''),c.feesCollected||0],['Operations reserve · 60% of fee',feeAllocation(c.feesCollected||0).operations],['Reviewer allocation · 40% of fee',feeAllocation(c.feesCollected||0).credits],['Reviewer credits awarded for this campaign',c.reviewerAwarded?c.reviewerBudget:0],['Each reviewer’s campaign award',c.reviewerAwarded?c.reviewerBudget/2:0],['Total contribution charges',c.raised+(c.feesCollected||0)],['Held in escrow',c.raised-c.released-c.refundPaid],['Supplier payments',c.released],['Refunds paid',c.refundPaid]].map(([l,v])=>`<div><span>${l}</span><strong>${money(v)}</strong></div>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Milestone / recipient</th><th>Fixed budget</th><th>Review</th><th>Payment</th><th>Delivery</th></tr></thead><tbody>${c.milestones.map(m=>`<tr><td>${esc(m.title)}<small class="ledger-name">${esc(who(m.supplier))}</small></td><td>${money(m.amount)}</td><td>${m.rejected?'Changes requested':m.hash===ZeroHash?'No evidence':((m.approvals&1?1:0)+(m.approvals&2?1:0))+'/2 approvals'}</td><td>${m.paid?'Released':'Held'}</td><td>${esc(m.delivery?.status||'Not recorded')}</td></tr>`).join('')}</tbody></table></div>${workflow.costReport(c)}</section>`).join(''):`<section class="panel empty"><h2>No projects for this account yet.</h2><p>Choose Asha Lim to see the example reports, or create a project under an organisation account.</p>${admin.unlocked?button('Use sample organiser','account:2','','users'):''}${button('Create project','create','primary','plus')}</section>`}`;}

function overview() {
  return `${heading('A little kindness goes a long way.','Community stories. Thoughtful giving. A plan you can follow.',button('Export report','export','', 'download')+button('Create campaign','create','primary','plus'))}
  <section class="hero charity-hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span>For the good we can do together</div><h2>Small acts.<br><em>Something bigger.</em></h2><p>A book for a new beginning. A meal shared with a neighbour. Give to a clear plan, and follow your kindness all the way.</p><div class="buttons">${button('Find a cause','nav:campaigns','lime','heart')}${button('Create your account','new-account','','plus')}</div><span class="illustration-note">Representative photography · sample projects</span></div>${heroArt()}</section>
  <div class="sandbox-note">${icon('wallet')}<div><strong>${esc(identities[actor].name)} · ${money(chain.balances[actor])} available</strong><span> Your wallet is connected to every donation, payment and refund.</span></div>${button('My account','nav:accounts','','arrow')}</div>
  ${stats()}<section><div class="section-heading"><div><h2>Find a purpose close to your heart</h2><p>Current campaigns use a 1% fee added at checkout. All campaigns use the current 1% fee and reviewer-credit rules. Photos are representative.</p></div>${filters()}</div><div class="campaign-grid">${filteredCampaigns().slice(0,3).map(card).join('')||empty('No campaigns here yet','Create a campaign to start something good.')}</div></section>
  <div class="lower-grid"><section class="panel"><div class="panel-header"><h2>A trail of good</h2>${button('View ledger','nav:ledger','ghost','arrow')}</div>${chain.audit.slice(0,4).map(activity).join('')}</section>
  <section class="panel"><h2>Trust, built into the process.</h2><div class="trust-flow"><span>1</span><div><strong>Give to a clear purpose</strong><p>Your contribution stays in escrow until the campaign’s rules are met.</p></div></div><div class="trust-flow"><span>2</span><div><strong>Two reviewer approvals</strong><p>Both assigned reviewer accounts approve each milestone before money moves.</p></div></div><div class="trust-flow"><span>3</span><div><strong>Follow the funds to the supplier</strong><p>Every release is tied to an agreed amount, recipient and evidence.</p></div></div><div class="trust-footer">${icon('shield')}Shared records. Accountable giving.</div></section></div>`;
}
function filters() {return `<div class="filters" role="group" aria-label="Filter campaigns">${['All','Funding','Active','Completed','Refunds'].map(f=>`<button class="filter ${filter===f?'active':''}" data-action="filter:${f}" aria-pressed="${filter===f}">${f==='Active'?'Fully funded':f==='Completed'?'Payments released':f}</button>`).join('')}</div>`;}
function filteredCampaigns(){return chain.campaigns.filter(c=>(!c.archived&&(filter==='All'||c.status===filter))&&`${c.title} ${c.category} ${c.location}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>(a.scenarioOrder??100)-(b.scenarioOrder??100));}
function card(c) {return `<article class="campaign-card" tabindex="0" role="button" aria-label="Open ${esc(c.title)}" data-action="campaign:${c.address}"><div class="campaign-image"><img src="/assets/${esc(campaignPhoto(c))}.jpg" alt="${esc(c.photoAlt||c.category||'Community campaign')} · representative photograph">${campaignBadge(c)}<span class="photo-caption">Representative photo · sample project</span></div><div class="card-body"><div class="card-category">${icon(c.category==='Education'?'book':c.category==='Environment'?'leaf':'heart')}${esc(c.category||'Community')}</div><h3>${esc(c.title)}</h3><p class="campaign-story">${esc(campaignDescription(c))}</p><p class="campaign-organiser">Organised by <strong>${esc(who(c.organiser))}</strong></p><div class="card-location">${icon('pin')}${esc(c.location||'Community campaign')}</div><div class="progress" aria-label="${Math.round(c.raised/c.target*100)} percent funded"><span style="width:${c.raised/c.target*100}%"></span></div><div class="card-amount"><strong>${money(c.raised)} <small>raised</small></strong><span>of ${money(c.target)}</span></div><div class="card-footer"><span>${icon('shield')}${c.milestones.filter(m=>m.paid).length}/${c.milestones.length} milestones paid</span><span class="link">Meet this cause ${icon('arrow')}</span></div></div></article>`;}
function campaignPage(){return `${heading('Give with clarity.','Current campaigns add a 1% fee. Each donation includes a separate fee and a visible allocation.',button('Create campaign','create','primary','plus'))}<div class="toolbar">${filters()}<label class="search">${icon('search')}<input id="campaign-search" placeholder="Search campaigns…" aria-label="Search campaigns" value="${esc(query)}"></label></div><div class="campaign-grid full-grid" id="campaign-results">${filteredCampaigns().map(card).join('')||empty('No campaigns found','Try a different search or filter.')}</div>`;}
function eventText(e) {
  const a=e.args;
  switch(e.name){case'CampaignCreated':return ['Campaign created',who(a.organiser),'leaf','Terms recorded'];case'Donated':return ['A contribution received',who(a.donor),'heart',`+${money(dollars(BigInt(a.amount)))}`];case'FeeCharged':return ['1% platform fee collected',who(a.donor),'receipt',money(dollars(BigInt(a.fee)))];case'ReviewerCreditsAwarded':return ['Donation credits awarded',who(a.reviewer),'heart',money(dollars(BigInt(a.amount)))];case'ReviewerCreditsSpent':return ['Donation credits used',who(a.reviewer),'heart',money(dollars(BigInt(a.total)))];case'ReviewerCreditsRestored':return ['Refund restored as donation credits',who(a.reviewer),'wallet',money(dollars(BigInt(a.amount)))];case'CreditRefunded':return ['Refund source breakdown',who(a.donor),'wallet',`${money(dollars(BigInt(a.credits)))} credits / ${money(dollars(BigInt(a.wallet)))} wallet`];case'FeeAllocated':return ['Fee reserves allocated',who(a.donor),'receipt',`${money(dollars(BigInt(a.operations)))} operations / ${money(dollars(BigInt(a.reviewerCredits)))} reviewer reserve`];case'EvidenceSubmitted':return ['Milestone evidence submitted',`Milestone ${Number(a.milestone)+1} · revision ${a.revision}`,'file','Ready for review'];case'Reviewed':return [a.approved?'Positive review recorded':'Changes requested',who(a.reviewer),'shield',a.approved?'Check current invoice approvals':'Request rejected'];case'SupplierPaid':return ['Payment sent to supplier',who(a.supplier),'send',money(dollars(BigInt(a.amount)))];case'RefundsOpened':return ['Refunds opened','Unspent funds reserved for donors','wallet',money(dollars(BigInt(a.pool)))];case'Refunded':return ['Donor refund paid',who(a.donor),'wallet',money(dollars(BigInt(a.amount)))];default:return [e.name,'','receipt','Recorded'];}
}
function activity(e){const [label,person,i,value]=eventText(e);return `<div class="activity-row"><span class="activity-icon">${icon(i)}</span><div class="activity-copy"><strong>${label}</strong><p>${esc(person)} · ${esc(e.title)}</p></div><div class="activity-amount">${value}<button data-action="tx:${e.hash}">Block ${e.block} · view proof ↗</button></div></div>`;}
function empty(title,message){return `<div class="empty">${icon('leaf')}<h3>${title}</h3><p>${message}</p></div>`;}

function detailPage(){
  const c=current();if(!c)return empty('Campaign not found','Choose a campaign from the overview.');
  return `<div class="page-heading"><div>${button('All campaigns','nav:campaigns','ghost','back')}</div><div class="buttons">${button('View payment trail',`ledger:${c.address}`,'','receipt')}${admin.unlocked?button('Scenario controls',`scenario-open:${c.address}`,'','clock'):''}${button('Rules & fees',`governance:${c.address}`,'','shield')}${button('Export report','export','','download')}</div></div>
  <section class="detail-hero"><img src="/assets/${esc(campaignPhoto(c))}.jpg" alt="${esc(c.photoAlt||c.category)} · representative photograph"><div class="detail-copy">${campaignBadge(c)}<h1>${esc(c.title)}</h1><p class="campaign-organiser">Organised by <strong>${esc(who(c.organiser))}</strong><span>Community organiser</span></p><p>${esc(campaignDescription(c))}</p><p class="delivery-status"><strong>${esc(c.deliveryStatus)}</strong> · Supplier payment and delivery acceptance are recorded separately.</p><div class="detail-meta"><span>${icon('pin')}${esc(c.location)}</span><span>${icon('leaf')}${esc(c.category)}</span></div></div></section>
  ${donationFlows.campaignLinks(c)}${experience.timeline(c)}<div class="detail-grid"><div class="detail-stack"><section class="panel"><div class="panel-header"><h2>A plan you can follow</h2><span class="rule-chip">${icon('shield')}2 assigned reviewers</span></div><p style="font-size:11px;color:#929d88;margin:0">Every milestone has a fixed supplier and budget. Both reviewers must approve its evidence.</p>${c.milestones.map(m=>milestone(c,m)).join('')}</section><section class="panel"><div class="panel-header"><h2>This campaign’s trail</h2>${button('All transactions',`ledger:${c.address}`,'ghost','arrow')}</div>${chain.audit.filter(e=>equal(e.campaign,c.address)).slice(0,5).map(activity).join('')}</section></div>
  <div class="detail-stack"><section class="panel fund-panel"><h2>Campaign funds, protected.</h2><div class="big">${money(c.raised)} <small>of ${money(c.target)} raised</small></div><div class="progress"><span style="width:${c.raised/c.target*100}%"></span></div><div class="balance-row"><span>Held in escrow</span><strong>${money(c.raised-c.released-c.refundPaid)}</strong></div><div class="balance-row"><span>Paid to suppliers</span><strong>${money(c.released)}</strong></div><div class="balance-row"><span>Platform fees collected separately</span><strong>${money(c.feesCollected||0)}</strong></div><div class="balance-row"><span>Your contribution</span><strong>${money(c.contributions[actor])}</strong></div><hr>${fundAction(c)}</section>
  <section class="panel"><h2>The rules behind the giving</h2><ul class="rule-list"><li>${icon('lock')}Funds are held until the full target is reached.</li><li>${icon('shield')}Two distinct reviewers approve each request.</li><li>${icon('send')}Payments go only to the agreed suppliers.</li><li>${icon('check')}Every milestone can be paid only once.</li><li>${icon('wallet')}After a missed deadline, donors share the unspent balance.</li></ul><div class="rules-kv"><p><span>Organiser</span><strong>${esc(who(c.organiser))}</strong></p><p><span>Funding deadline</span><strong>${date(c.fundingDeadline)}</strong></p><p><span>Delivery deadline</span><strong>${date(c.deliveryDeadline)}</strong></p><p><span>Reviewers</span><strong>${c.reviewers.map(who).map(esc).join(' + ')}</strong></p></div><p class="hash">Contract: ${esc(c.address)}</p>${button('Inspect fixed terms',`terms:${c.address}`,'ghost','file')}</section>${experience.trust(c)}</div></div>`;
}
function donationEstimate(c,amount){try{const q=chain.quoteDonation(c.address,amount);return `<div class="balance-row"><span>1% fee</span><strong>${money(q.fee)}</strong></div><div class="balance-row"><span>Total to authorise</span><strong>${money(q.total)}</strong></div><p>Fee allocation: ${money(q.operations)} operations · ${money(q.credits)} reviewer credits. Each reviewer’s allocation from this fee: ${money(q.credits/2)} after both participate.</p>`;}catch{return '<p>Enter a valid donation amount to see its fee.</p>';}}
function updateDonationEstimate(){const form=document.querySelector('#donation-form'),node=document.querySelector('#donation-estimate');if(form&&node)node.innerHTML=donationEstimate(chain.campaigns.find(c=>equal(c.address,form.dataset.campaign)),form.elements.amount.value);}
function fundAction(c){
  if(c.archived&&c.status==='Funding')return '<div class="notice"><strong>Earlier contract version.</strong> New donations use the current 1% contracts. Existing funds, fees, payments and refund rights remain recorded here.</div>'+button('Choose a current campaign','nav:campaigns','primary','heart');
  if(c.status==='Funding')return `<form id="donation-form" data-campaign="${c.address}"><div class="field"><label for="donation-amount">Donation amount (SGD)</label><div class="currency-input"><span>SGD</span><input id="donation-amount" name="amount" type="number" min="0.01" max="${c.target-c.raised}" step="0.01" value="${Math.min(100,c.target-c.raised)}" required></div></div><div class="quick-amounts">${[25,50,100,250].filter(v=>v<=c.target-c.raised).map(v=>`<button type="button" data-action="amount:${v}">${money(v)}</button>`).join('')}</div><div id="donation-estimate" aria-live="polite">${donationEstimate(c,Math.min(100,c.target-c.raised))}</div><div class="field"><label for="donation-source">Pay using</label><select id="donation-source" name="source"><option value="wallet">Wallet balance · ${money(chain.balances[actor])}</option>${chain.reviewerCredits[actor]>0?`<option value="credits">Donation-only reviewer credits · ${money(chain.reviewerCredits[actor])}</option>`:''}</select></div><button class="btn primary wide" ${busy?'disabled':''}>${icon('heart')}Review donation</button></form><div class="notice">Available wallet balance: <strong>${money(chain.balances[actor])}</strong><br>Your donation goes to escrow. A separate 1% platform fee is added to the wallet deduction and retained on refunds.</div>`;
  if(c.status==='Refunds') {
    const eligible=c.contributions[actor]>0&&!c.refunded[actor];
    const pool=c.refundPool||c.raised-c.released;
    const refundEvent=chain.audit.find(e=>e.name==='Refunded'&&equal(e.campaign,c.address)&&equal(e.args.donor,identities[actor].address));
    const share=refundEvent?dollars(BigInt(refundEvent.args.amount)):(c.raised?pool*c.contributions[actor]/c.raised:0);
    return `<h3 style="font-size:14px">Unspent funds can come home.</h3><p class="notice">The deadline passed. Supplier payments are closed. Refunds are proportional to each donor’s contribution. Wallet-funded principal returns to the wallet; credit-funded principal returns as donation-only credits. Platform fees are retained.</p><div class="balance-row"><span>Original refund pool</span><strong>${money(pool)}</strong></div><div class="balance-row"><span>Still held for refunds</span><strong>${money(Math.max(0,pool-c.refundPaid))}</strong></div><div class="balance-row"><span>${c.refunded[actor]?'Refund paid to you':'Your estimated share'}</span><strong>${money(share)}</strong></div>${eligible?button('Claim my refund',`claim:${c.address}`,'primary wide','wallet'):`<div class="notice">${c.refunded[actor]?'Your refund has already been paid.':'This identity has no donation to refund.'}</div>`}`;
  }
  return `<div class="notice">${c.status==='Completed'?'<strong>Supplier payments complete.</strong><br>All milestones have been paid to their suppliers. Explore the records below.':'<strong>Fully funded. Ready for good.</strong><br>Contributions are closed. The organiser and reviewers can now move each milestone forward.'}</div>${c.status==='Active'&&experience.role()==='reviewer'?button('View my review queue','nav:approvals','primary wide','shield'):button('See the payment trail',`ledger:${c.address}`,'primary wide','receipt')}`;
}
function milestone(c,m){
  let state=m.paid?'Payment released':m.rejected?'Rejected':m.hash===ZeroHash?'Not submitted':m.approvals===3?'Approved':'Pending';
  const organiser=equal(c.organiser,identities[actor].address),reviewer=c.reviewers.findIndex(r=>equal(r,identities[actor].address));
  let actions='';
  if(c.status==='Active'&&!m.paid){
    if(organiser&&(m.hash===ZeroHash||m.rejected))actions+=button(m.rejected?'Submit revised evidence':'Submit evidence',`evidence:${c.address}:${m.id}`,'primary','file');
    if(reviewer>=0&&m.hash!==ZeroHash&&(!m.rejected||c.rewardEnabled)&&!(m.reviewParticipation&(reviewer===0?1:2))){
      if(!(m.approvals&(reviewer===0?1:2)))actions+=button(m.rejected?'Record positive review · payment stays blocked':'Approve request',`approve:${c.address}:${m.id}`,'primary','check');
      actions+=button('Request changes',`reject:${c.address}:${m.id}`,'danger','x');
    }
    if(m.approvals!==3)actions+=button('Check release conditions',`guard:${c.address}:${m.id}`,'','lock');
    if(m.approvals===3&&!m.rejected)actions+=button('Release supplier payment',`release:${c.address}:${m.id}`,'primary','send');
  }
  return `<div class="milestone"><div class="milestone-top"><div class="milestone-title"><span class="step-num">${m.paid?icon('check'):m.id+1}</span><div><h3>${esc(m.title)}</h3><p class="no-margin" style="margin-top:4px">Supplier: ${esc(who(m.supplier))}</p></div></div><div class="milestone-amount">${money(m.amount)}</div></div><div style="margin-top:12px">${badge(state)}</div>${m.hash!==ZeroHash?`<div class="approval-track">${c.reviewers.map((r,i)=>`<span class="approval-person ${m.approvals&(i===0?1:2)?'yes':''}">${icon(m.approvals&(i===0?1:2)?'check':'clock')}${esc(who(r))}</span>`).join('')}</div><button class="evidence-link" data-action="inspect:${c.address}:${m.id}">${icon('file')}Evidence revision ${m.revision} · ${short(m.hash)} ${icon('chevron')}</button>`:`<p>The organiser will submit supporting evidence when this milestone is ready.</p>`}${c.rewardEnabled?`<div class="notice"><strong>Reviewer reward: ${money(c.reviewerBudget/2)} each</strong> · ${c.reviewerAwarded?'Awarded to both assigned reviewers':`${(c.rewardReviewMask&1?1:0)+(c.rewardReviewMask&2?1:0)} of 2 reviewers have participated`}. Split equally once both review, including rejections. One award per campaign; not per invoice. Donation-only credits, with no cash withdrawal.</div>`:''}${actions?`<div class="buttons" style="margin-top:13px">${actions}</div>`:''}${m.rejected?`<p>Reviewers requested changes. Any second review records participation but cannot reopen this invoice for payment. Fresh evidence resets both approvals.</p>${m.rejectionNote&&(organiser||reviewer>=0)?`<div class="notice"><strong>Reviewer’s note:</strong> ${esc(m.rejectionNote)}</div>`:''}`:''}${workflow.deliveryPanel(c,m)}</div>`;
}
function approvalPage(){
  const items=chain.campaigns.filter(c=>!c.archived&&c.status==='Active'&&c.reviewers.some(r=>equal(r,identities[actor].address))).flatMap(c=>c.milestones.filter(m=>m.hash!==ZeroHash&&!m.paid&&(!m.rejected||c.rewardEnabled)).map(m=>({c,m})));
  return `${heading('A second look makes a difference.','Review evidence before a single payment leaves escrow.','')}<div class="notice">Current identity: <strong>${esc(identities[actor].name)} · ${identities[actor].role}</strong>. Only the two reviewers assigned to a campaign can approve its requests.</div>${items.length?items.map(({c,m})=>`<section class="panel" style="margin-bottom:18px"><div class="panel-header"><div><h2>${esc(c.title)}</h2><p style="font-size:10px;color:#929f88;margin:5px 0 0">Immutable recipient and amount · Evidence fingerprint recorded on-chain</p></div>${button('Open campaign',`campaign:${c.address}`,'ghost','arrow')}</div>${milestone(c,m)}</section>`).join(''):`<section class="panel">${empty('All caught up','There are no submitted requests waiting for approval. Organisers can submit evidence from a funded campaign.')}</section>`}`;
}
function ledgerPage(){
  const rows=chain.audit.filter(e=>!selected||equal(e.campaign,selected));
  return `${heading('Every step leaves a record.','Follow contributions, approvals, supplier payments and refunds.',button('Export report','export','','download'))}<div class="toolbar"><div class="filters"><button class="filter ${!selected?'active':''}" data-action="ledger:all">All campaigns</button>${chain.campaigns.slice(0,5).map(c=>`<button class="filter ${equal(selected,c.address)?'active':''}" data-action="ledger:${c.address}">${esc(c.title.split(' ').slice(0,3).join(' '))}…</button>`).join('')}</div><span class="badge">${rows.length} recorded events</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Event / campaign</th><th>Participant</th><th>Amount / outcome</th><th>Block</th><th>Transaction proof</th></tr></thead><tbody>${rows.map(e=>{const [label,person,,value]=eventText(e);return `<tr><td>${label}<div class="ledger-name">${esc(e.title)}</div></td><td>${esc(person)}</td><td>${value}</td><td>#${e.block}</td><td><button class="btn ghost" data-action="tx:${e.hash}">${short(e.hash)} ${icon('chevron')}</button></td></tr>`;}).join('')}</tbody></table></div>${!rows.length?empty('No events yet','Campaign actions will appear here once mined.'):''}</section><div class="notice">These are genuine mined transactions on your browser-local chain. They are not published to Ethereum mainnet or a public block explorer.</div>`;
}
function aboutPage(){return `${heading('Giving, with proof.','ClearGive turns agreed funding rules into enforceable payment conditions.',button('See rules & fees','nav:governance','primary','shield'))}<div class="about-grid"><section class="panel"><h2>What ClearGive does</h2><p>Donors, organisers, independent reviewers and suppliers share one record of how donations move. Organisers cannot simply withdraw the whole balance.</p><h3>Current donation fee</h3><p>A 1% fee is added to the campaign donation and collected in the same contract transaction. SGD 100 to escrow costs SGD 101 in total. The fee vault reserves 60% for operations and 40% for reviewer credits. Platform fees are retained on campaign refunds. The reserves are virtual tokens, not actual server or gas payments.</p><h3>1. A fixed plan</h3><p>The organiser sets milestones, supplier addresses, budgets and deadlines before accepting donations. There is no admin override or upgrade function.</p><h3>2. Evidence, then approval</h3><p>A salted fingerprint of the evidence goes on-chain. Each reviewer approves that exact revision. Rejected evidence can be replaced, but approvals start again.</p><h3>3. A direct supplier payment</h3><p>With two approvals, anyone can trigger the agreed payment. The contract fixes who gets paid and how much, and prevents duplicate milestone payments.</p><h3>4. A defined way out</h3><p>If funding or delivery misses its deadline, further payments stop. Donors claim proportional shares of the remaining funds. Already spent funds cannot be refunded.</p></section><section class="panel"><h2>What this prototype demonstrates</h2><p>A real Ethereum Virtual Machine runs inside your browser using Ganache. Solidity contracts enforce every contribution, approval, release and refund. No real currency is used.</p><ul><li>Create personal and organisation accounts. An admin prepares fictional balances separately.</li><li>Create campaigns and define supplier milestones.</li><li>Review local sample evidence and verify its fingerprint.</li><li>Inspect real receipts, contract events and token balances.</li><li>Admins can run a complete guided scenario, stage by stage.</li><li>Reload to restore the chain by replaying saved transactions.</li></ul><div class="notice"><strong>A transparent record is not proof of delivery.</strong><br>People must still check suppliers, invoices and real-world outcomes. Two reviewers can collude. Identity checks and operational governance would be needed for a real service.</div></section><section class="panel"><h2>Privacy and trust boundaries</h2><p>Only salted evidence hashes are sent to the contract. Files and notes stay in this workspace; joining a shared classroom stores them in its cloud journal. Donors see the fingerprint; organiser and reviewer identities can inspect sample documents.</p><p>Role switching is a demo convenience, not secure authentication. All demo identities and browser data are controlled by the person using this browser. Production needs authenticated accounts, encrypted document storage, access policies and independent wallet signatures.</p><p>Public blockchain addresses, amounts and dates would remain visible. Sensitive medical records should not be placed on-chain.</p></section><section class="panel"><h2>Taking ClearGive beyond the demo</h2><ul><li>Deploy independently reviewed contracts to a public testnet.</li><li>Connect user-owned wallets; remove shared demo signers.</li><li>Verify charities, reviewers and suppliers independently.</li><li>Use secure evidence storage with explicit retention rules.</li><li>Decide jurisdiction, accepted currency and supplier cash-out process.</li><li>Commission a security audit before holding real donations.</li></ul><p>The initial scope is community projects with planned supplier purchases. Emergency advances, cash assistance and changing campaign purposes need separate rules.</p></section></div><div class="panel" style="margin-top:22px"><div class="panel-header"><h2>Your sandbox environment</h2><span class="badge active">Chain ID 1337</span></div><div class="info-row"><span>Demo token</span><span class="hash">${chain.record.deployments.token}</span></div><div class="info-row"><span>Factory</span><span class="hash">${chain.record.deployments.factory}</span></div><div class="info-row"><span>Chain clock</span><span>${new Date(chain.timestamp*1000).toLocaleString('en-SG',{timeZone:'Asia/Singapore'})} SGT</span></div><div class="buttons" style="margin-top:20px">${button('Export all records','export','','download')}${admin.unlocked?button('Reset demo environment','reset','danger','x'):''}</div><p class="report-toast">Your chain is saved in this workspace. Shared classrooms also keep a cloud journal. Export a report before clearing local data.</p></div>`;}
function tourPage(){const saved=chain.record.guidedJourney,j=saved?.address&&!chain.campaigns.some(c=>equal(c.address,saved.address))?null:saved;return `${heading('From a new account to a confirmed delivery.','Eight guided stages. Pause after each one to inspect what changed.')}${j?.address&&chain.campaigns.find(c=>equal(c.address,j.address))?.archived?'<div class="notice">This saved journey used an earlier contract version. Start a new journey to demonstrate the current 1% fee and 60/40 allocation. Earlier records stay unchanged.</div>':''}<section class="panel"><div class="panel-header"><h2>A complete community journey</h2><span class="badge">${j?.step||0} / 8 stages</span></div><p>Create new accounts with SGD 0, review organisations, open a SGD 100 campaign, contribute SGD 100 plus a SGD 1 fee (SGD 0.60 operations reserve; SGD 0.40 reviewer-credit reserve), approve the invoice, pay the supplier and confirm delivery. Presenter setup allocates SGD 200 separately before the contribution.</p><div class="tour-steps">${JOURNEY_STEPS.map((name,i)=>`<span class="tour-step ${j?.step>i?'done':j?.step===i?'running':''}">${j?.step>i?icon('check'):i+1} ${name}</span>`).join('')}</div>${j?`<div class="tour-log" aria-live="polite">${j.logs.map(t=>`<p>${esc(t)}</p>`).join('')}</div>`:''}<div class="buttons">${button(j?.step===8?'Start a new journey':j?JOURNEY_STEPS[j.step]:'Create new accounts','run-tour','primary','play')}${j?button('Inspect current account',`account:${j.actor}`,'','wallet'):''}${j?.address?button('Inspect campaign',`campaign:${j.address}`,'','arrow'):''}${j?.receipt?button('View donation receipt',`receipt:${j.receipt}`,'','receipt'):''}</div>${j?.step===8?`<div class="notice"><strong>Main journey complete.</strong> Donor balance after the main donation ${money(chain.record.donationReceipts[j.receipt]?.balanceAfter??100)}, supplier received SGD 100, escrow SGD 0 and delivery separately confirmed. Reviewer awards follow the campaign contract version; inspect the fee and reward records. This main journey does not advance the workspace clock.</div>`:''}</section><section class="panel"><h2>A separate refund example</h2><p>Give SGD 50 towards a different SGD 100 campaign. When its funding deadline passes, return the SGD 50 donation principal. The separate SGD 0.50 platform fee is retained: SGD 0.30 operations reserve and SGD 0.20 reviewer-credit reserve. This advances the clock for the whole workspace; already-paid funds cannot be refunded.</p>${j?.refundDone?`<div class="notice">SGD 50 donation principal refunded; the separate fee stays in its vault with a 60% operations / 40% reviewer-credit allocation. Historical zero-fee examples retain their original rules. This campaign never reached its target and paid no supplier.</div>${button('Inspect refund campaign',`campaign:${j.refundAddress}`,'','wallet')}`:j?.step===8?button(j.refundAddress?'Resume refund example':'Prepare refund example','refund-tour-confirm','','clock'):'<p>Complete the main journey first.</p>'}</section><div class="notice">Guided actions use actual contracts on the local EVM. Organisation and delivery statements are signed off-chain. One presenter operates the sandbox accounts; their distinct addresses do not establish independent people.</div>`;}

async function inspectEvidence(address,id){
  const c=chain.campaigns.find(c=>equal(c.address,address)),m=c.milestones[id],doc=chain.record.evidence[m.hash];
  const mayView=equal(c.organiser,identities[actor].address)||c.reviewers.some(r=>equal(r,identities[actor].address));
  const content=mayView&&doc?`<div class="file-tag">${icon('file')}<div><strong>${esc(doc.name||'Supporting evidence')}</strong><p>${doc.sample?'Fictional sample evidence':'Stored in this browser'}</p></div></div><p class="evidence-note">${esc(doc.note)}</p>${doc.invoiceNumber?`<div class="rules-kv"><p><span>Invoice</span><strong>${esc(doc.invoiceNumber)} · ${esc(doc.invoiceDate)}</strong></p><p><span>Items</span><strong>${esc(doc.items)}</strong></p><p><span>Quantity × unit price</span><strong>${doc.quantity} × ${money(doc.unitPrice)}</strong></p><p><span>Expected delivery</span><strong>${esc(doc.expectedDelivery)}</strong></p><p><span>Supplier checks</span><strong>${esc(doc.supplierCheck)}</strong></p></div>`:''}${doc.fileDigest?`<p class="hash">File SHA-256: ${esc(doc.fileDigest)}</p>`:''}<div class="document-actions">${button('Verify fingerprint',`verify:${m.hash}`,'','shield')}${doc.fileData?button('Download evidence',`download-evidence:${m.hash}`,'','download'):''}</div><div id="verify-result"></div>`:`<div class="notice">The document’s fingerprint is public. Switch to this campaign’s organiser or a reviewer to inspect the supporting evidence. Account switching does not provide secure authentication.</div>`;
  openModal('Evidence & its proof',`Milestone ${id+1} · revision ${m.revision}`,`<div class="modal-body">${content}<section class="evidence-payment-summary"><h3>Compare with the agreed payment</h3><div class="balance-row"><span>Fixed supplier</span><strong>${esc(who(m.supplier))}</strong></div><div class="balance-row"><span>Agreed budget</span><strong>${money(m.amount)}</strong></div><div class="balance-row"><span>Supplier registration review</span><strong>${esc(chain.verification(m.supplier).status)}</strong></div>${c.reviewers.map((r,i)=>`<div class="balance-row"><span>${esc(who(r))}</span><strong>${m.approvals&(1<<i)?'Approved this revision':'Approval pending'}</strong></div>`).join('')}<p class="section-copy">Distinct sandbox addresses do not prove that independent people performed these checks.</p></section><h3 style="font-size:12px;margin-top:22px">Fingerprint recorded on-chain</h3><p class="hash">${m.hash}</p><div class="notice">A matching fingerprint shows that the evidence has not changed. It does not establish that its contents are true.</div></div>`);
}
function evidenceForm(address,id){
  const c=chain.campaigns.find(c=>equal(c.address,address)),m=c.milestones[id];
  openModal('Give reviewers something to check',m.title,`<form id="evidence-form" data-campaign="${address}" data-milestone="${id}"><div class="modal-body">${workflow.evidenceFields()}<div class="field"><label for="evidence-name">Document name</label><input id="evidence-name" name="name" value="${esc(who(m.supplier))} quotation" maxlength="120" required></div><div class="field"><label for="evidence-note">Order details and verification notes</label><textarea id="evidence-note" name="note" placeholder="Explain the items, quantities, quote reference and how the supplier was verified…" maxlength="3000" required></textarea></div><div class="field"><label for="evidence-file">Attach sample evidence (optional)</label><input id="evidence-file" type="file" accept=".pdf,.txt,.png,.jpg,.jpeg,.json"><small>Use fictional sample documents only. Maximum 250 KB. Files stay in this workspace; a shared classroom includes them. Only their salted evidence fingerprint goes on-chain.</small></div><div class="notice">Recipient: <strong>${esc(who(m.supplier))}</strong> · Amount: <strong>${money(m.amount)}</strong><br>These campaign terms cannot be changed by submitting evidence.</div><p class="inline-error" id="form-error"></p></div><div class="modal-footer"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">Record evidence</button></div></form>`);
}
function rejectForm(address,id){openModal('Request a clearer explanation','Rejecting a request resets its approvals.',`<form id="reject-form" data-campaign="${address}" data-milestone="${id}"><div class="modal-body"><div class="field"><label for="rejection-reason">What needs to change?</label><textarea id="rejection-reason" name="reason" placeholder="Explain the missing or inconsistent evidence…" required maxlength="2000"></textarea></div><p class="inline-error" id="form-error"></p></div><div class="modal-footer"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn danger">Reject this revision</button></div></form>`);}
async function transactionModal(hash){
  const t=await chain.transaction(hash);
  openModal('A verifiable payment trail','Mined receipt from your browser-local Ethereum chain.',`<div class="modal-body"><span class="badge active">${icon('check')}Transaction confirmed</span><div class="info-row"><span>Hash</span><span class="hash">${hash}</span></div><div class="info-row"><span>From</span><span>${esc(who(t.from))}<br><span class="hash">${t.from}</span></span></div><div class="info-row"><span>To</span><span class="hash">${t.to}</span></div><div class="info-row"><span>Block</span><span>#${t.block}</span></div><div class="info-row"><span>Time</span><span>${new Date(t.timestamp*1000).toLocaleString('en-SG',{timeZone:'Asia/Singapore'})} SGT</span></div><div class="info-row"><span>Gas used</span><span>${t.gasUsed}</span></div><h3 style="font-size:12px;margin:20px 0 8px">Decoded contract events</h3><div class="source-code">${esc(JSON.stringify(t.events.map(e=>({event:e.name,...e.args})),null,2))}</div><div class="notice">This transaction exists on the local demo chain. It has no public block-explorer link.</div></div>`,`<div class="modal-footer">${button('Copy transaction hash',`copy:${hash}`,'','copy')}</div>`);
}
function termsModal(address){const c=chain.campaigns.find(c=>equal(c.address,address)),meta=chain.record.metadata[address.toLowerCase()];openModal('The campaign’s fixed commitment','These terms were fingerprinted before the first donation.',`<div class="modal-body"><div class="terms-preview"><h3>${esc(c.title)}</h3>${c.contractTitle&&c.contractTitle!==c.title?`<p>Public campaign name updated for clarity. The original contract remains registered as <strong>${esc(c.contractTitle)}</strong>.</p>`:''}<div class="terms-line"><span>Total budget</span><strong>${money(c.target)}</strong></div><div class="terms-line"><span>Donation fee</span><strong>${c.legacy?'Earlier zero-fee contract':'1% added, retained on refunds'}</strong></div><div class="terms-line"><span>Fee allocation</span><strong>${c.legacy?'No fee collected':'60% operations reserve · 40% reviewer-credit reserve'}</strong></div><div class="terms-line"><span>Funding closes</span><strong>${date(c.fundingDeadline)}</strong></div><div class="terms-line"><span>Delivery due</span><strong>${date(c.deliveryDeadline)}</strong></div>${c.milestones.map(m=>`<div class="terms-line"><span>${esc(m.title)} → ${esc(who(m.supplier))}</span><strong>${money(m.amount)}</strong></div>`).join('')}</div><p class="hash">On-chain terms fingerprint: ${c.termsHash}</p><div class="verify-result">${meta&&fingerprint(Object.fromEntries(Object.entries(meta).filter(([k])=>!['termsHash','createdAt'].includes(k))))===c.termsHash?'Local campaign metadata matches its original on-chain fingerprint.':'Contract terms are read directly from the chain. Inspect the exported report for local metadata.'}</div><div class="notice">No admin can rewrite milestone amounts, supplier addresses or deadlines. The campaign must reach its whole funding target before any supplier payment.</div></div>`);}

function createWizard(){
  if(!business(identities[actor],actor)){chooseOrganisation();return;}if(!chain.registrationApproved(identities[actor].address)){openModal('Complete the organisation review first','Your organising account stays selected.',`<div class="modal-body"><p>${esc(identities[actor].name)} needs a signed registration review before opening a campaign. Submit its details, then have a reviewer assess them.</p></div>`,`<div class="modal-footer">${button('Open organisation review','nav:registration','primary','shield')}</div>`);return;}render();wizardStep=0;
  draft={owner:actor,reviewers:[chain.accounts[3],chain.accounts[4]],costs:[],title:'',description:'',category:'Education',location:'Singapore',image:'school',fundingDays:14,deliveryDays:30,milestones:[{title:'',supplier:chain.accounts[actor===5?6:5],amount:''}]};wizardRender();
}
function wizardRender(){
  let fields;
  if(wizardStep===0)fields=`<div class="form-grid"><div class="field full"><label for="campaign-owner">Organising account</label><select id="campaign-owner" name="owner">${identities.map((id,i)=>business(id,i)?`<option value="${i}" ${draft.owner===i?'selected':''}>${esc(id.name)} · ${esc(chain.verification(id.address).status)}</option>`:'').join('')}</select></div><div class="field"><label for="reviewer-one">Reviewer 1</label><select id="reviewer-one" name="reviewer1">${identities.map((id,i)=>isReviewer(i)?`<option value="${id.address}" ${equal(draft.reviewers[0],id.address)?'selected':''}>${esc(id.name)}</option>`:'').join('')}</select></div><div class="field"><label for="reviewer-two">Reviewer 2</label><select id="reviewer-two" name="reviewer2">${identities.map((id,i)=>isReviewer(i)?`<option value="${id.address}" ${equal(draft.reviewers[1],id.address)?'selected':''}>${esc(id.name)}</option>`:'').join('')}</select></div><div class="field full"><label for="campaign-title">Campaign title</label><input id="campaign-title" name="title" value="${esc(draft.title)}" placeholder="What will your community achieve?" required minlength="5" maxlength="100"></div><div class="field full"><label for="campaign-description">Purpose and expected impact</label><textarea id="campaign-description" name="description" placeholder="Who benefits, what will you buy, and how will delivery be checked?" required minlength="20" maxlength="2000">${esc(draft.description)}</textarea></div><div class="field"><label for="campaign-category">Category</label><select id="campaign-category" name="category">${['Education','Food security','Environment','Community'].map(v=>`<option ${draft.category===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="campaign-location">Community / location</label><input id="campaign-location" name="location" value="${esc(draft.location)}" required maxlength="100"></div><div class="field"><label for="funding-days">Days to raise the full target</label><input id="funding-days" name="fundingDays" type="number" min="1" max="365" value="${draft.fundingDays}" required></div><div class="field"><label for="delivery-days">Delivery days after funding closes</label><input id="delivery-days" name="deliveryDays" type="number" min="1" max="365" value="${draft.deliveryDays}" required></div></div>${workflow.costFields(draft)}<div class="notice">Campaign owner: <strong>${esc(identities[draft.owner].name)}</strong> · Reviewers: <strong>${draft.reviewers.map(who).map(esc).join(' and ')}</strong><br>The organiser and selected suppliers need approved registration reviews. Each reviewer must have no undisclosed conflict.</div>`;
  else if(wizardStep===1)fields=`<p style="font-size:11px;color:#859774;margin:0 0 18px">Each milestone pays one fixed supplier. The target is the sum of these budgets.</p>${draft.milestones.map((m,i)=>`<div class="milestone-input"><div class="row-title"><span>Milestone ${i+1}</span>${draft.milestones.length>1?`<button type="button" class="close" data-action="remove-milestone:${i}" aria-label="Remove milestone ${i+1}">${icon('x')}</button>`:''}</div><div class="field"><label for="m-title-${i}">What will be purchased?</label><input id="m-title-${i}" name="mTitle${i}" value="${esc(m.title)}" placeholder="e.g. Books and learning materials" required maxlength="120"></div><div class="form-grid"><div class="field"><label for="m-supplier-${i}">Supplier organisation</label><select id="m-supplier-${i}" name="mSupplier${i}">${recipientOptions().map(id=>`<option value="${id.address}" ${equal(m.supplier,id.address)?'selected':''}>${esc(id.name)}</option>`).join('')}</select></div><div class="field"><label for="m-amount-${i}">Budget (SGD)</label><input id="m-amount-${i}" name="mAmount${i}" type="number" min="0.01" max="50000" step="0.01" value="${m.amount}" placeholder="1,000" required></div></div></div>`).join('')}${draft.milestones.length<8?button('Add a milestone','add-milestone','','plus'):''}`;
  else fields=`<div class="terms-preview"><h3>${esc(draft.title)}</h3><p>${esc(draft.description)}</p><div class="terms-line"><span>Community</span><strong>${esc(draft.location)}</strong></div><div class="terms-line"><span>Total target</span><strong>${money(draft.milestones.reduce((n,m)=>n+Number(m.amount),0))}</strong></div><div class="terms-line"><span>Donation fee</span><strong>1% added to each donation; retained on refunds</strong></div><div class="terms-line"><span>Fee allocation</span><strong>60% operations reserve · 40% reviewer-credit reserve</strong></div><div class="terms-line"><span>Funding period</span><strong>${draft.fundingDays} days</strong></div><div class="terms-line"><span>Delivery after funding deadline</span><strong>${draft.deliveryDays} days</strong></div>${draft.milestones.map(m=>`<div class="terms-line"><span>${esc(m.title)} → ${esc(who(m.supplier))}</span><strong>${money(Number(m.amount))}</strong></div>`).join('')}</div><ul class="rule-list"><li>${icon('shield')}Two independent approvals for each payment.</li><li>${icon('lock')}No organiser withdrawal or admin override.</li><li>${icon('wallet')}Missed deadlines open proportional refunds of unspent funds.</li></ul><label class="check-label"><input name="confirmed" type="checkbox" required>I understand that these campaign rules become fixed when the contract is created and confirm that relevant conflicts have been disclosed.</label>`;
  openModal('Start something good.', 'Build a campaign with a clear purpose and a verifiable plan.',`<div class="stepper">${['01 · Purpose','02 · Milestones','03 · Confirm rules'].map((s,i)=>`<span class="${i<=wizardStep?'active':''}">${s}</span>`).join('')}</div><form id="campaign-form"><div class="modal-body">${fields}<p class="inline-error" id="form-error"></p></div><div class="modal-footer">${wizardStep>0?'<button type="button" class="btn" data-action="wizard-back">Back</button>':'<button type="button" class="btn" data-action="close-modal">Cancel</button>'}<button class="btn primary">${wizardStep===2?'Create campaign contract':'Continue'}${icon('arrow')}</button></div></form>`);
}
function readDraft(){
  const form=document.querySelector('#campaign-form');if(!form)return;
  const data=new FormData(form);
  if(wizardStep===0){draft.reviewers=[String(data.get('reviewer1')),String(data.get('reviewer2'))];draft.costs=['Administration','Review','Gas','Storage'].map((category,i)=>({category,amount:Number(data.get('cost'+i)||0),payer:String(data.get('payer'+i)||'Project sponsor').trim()}));draft.owner=Number(data.get('owner'));draft.milestones=draft.milestones.map(m=>equal(m.supplier,chain.accounts[draft.owner])?{...m,supplier:recipientOptions()[0].address}:m);for(const name of ['title','description','category','location'])draft[name]=String(data.get(name)||'').trim();draft.fundingDays=Number(data.get('fundingDays'));draft.deliveryDays=Number(data.get('deliveryDays'));draft.image=draft.category==='Food security'?'pantry':draft.category==='Environment'?'garden':'school';}
  if(wizardStep===1)draft.milestones=draft.milestones.map((m,i)=>({title:String(data.get(`mTitle${i}`)||'').trim(),supplier:String(data.get(`mSupplier${i}`)),amount:String(data.get(`mAmount${i}`)||'')}));
}
async function guidedDemo(){await run('Running the next journey stage…',async()=>{const j=await advanceJourney(chain);actor=j.actor;},'Journey stage complete. Inspect the account or campaign before continuing.');go('tour');}
function chooseOrganisation(){if(!admin.unlocked){newAccount('business');return;}openModal('Choose an organising account','Starting a campaign requires an organisation account.',`<form id="organiser-choice-form"><div class="modal-body"><p>You are currently using ${esc(identities[actor].name)}. Choose an organisation explicitly, or create a new one.</p><div class="field"><label for="organiser-choice">Organisation</label><select id="organiser-choice" name="owner">${identities.map((id,i)=>business(id,i)?`<option value="${i}">${esc(id.name)} · ${esc(chain.verification(id.address).status)}</option>`:'').join('')}</select></div><p class="inline-error" id="form-error"></p></div><div class="modal-footer">${button('Create organisation account','new-organisation','','plus')}<button class="btn primary">Continue as this organisation</button></div></form>`);}

async function exportReport(){const report=await chain.exportReport();const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'});download(blob,`cleargive-report-${new Date().toISOString().slice(0,10)}.json`);toast('Campaigns, contract addresses and transaction events exported.');}
function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

document.addEventListener('click',async e=>{
  const element=e.target.closest('[data-action]');if(!element)return;e.preventDefault();
  if(busy||sharedUI.syncing)return;
  const [action,...args]=element.dataset.action.split(':');
  try{if(ADMIN_ACTIONS.has(action))admin.require();if(await sharedUI.action(action,args)||await workflow.action(action,args))return;switch(action){
    case'nav':go(args[0]);break;
    case'admin-exit':admin.close();history.replaceState(null,'','/demo');go('overview');toast('Participant view is ready. Demo controls remain available from the menu.');break;
    case'governance':governance.campaign=args[0]||null;go('governance');break;
    case'new-account':newAccount();break;
    case'new-organisation':newAccount('business');break;
    case'presenter-select':{actor=Number(document.querySelector('#presenter-account').value);admin.close();history.replaceState(null,'','/demo');go('overview');break;}
    case'fund':await run('Adding virtual scenario funds…',()=>chain.setBalance(Number(args[0]),chain.balances[Number(args[0])]+Number(args[1])),'Virtual funds added.');break;
    case'receipt':experience.receipt(args[0]);break;
    case'flow':donationFlows.selectedMilestone=null;go('donationflow',args[0]);break;
    case'flow-order':donationFlows.selectedMilestone=Number(args[1]);selected=args[0];view='donationflow';render();break;
    case'refund-tour-confirm':openModal('Run the separate refund example?','This advances the clock for every campaign in the workspace.',`<div class="modal-body"><p>A new campaign receives SGD 50, misses its funding target and returns SGD 50 to the donor. Other campaigns with earlier deadlines will also expire. The platform fee is not included in the refund.</p></div>`,`<div class="modal-footer">${button('Cancel','close-modal','')}${button('Run refund example','refund-tour-run','primary','clock')}</div>`);break;
    case'refund-tour-run':modal.close();await run('Demonstrating a missed funding deadline…',async()=>{const j=chain.record.guidedJourney.refundAddress?await finishRefundJourney(chain):await runRefundJourney(chain);actor=j.actor;},'SGD 50 returned to the donor.');go('tour');break;
    case'account':actor=Number(args[0]);go('accounts');toast('Now using '+identities[actor].name);break;
    case'balance':balanceForm(Number(args[0]));break;
    case'campaign':go('detail',args[0]);break;
    case'ledger':go('ledger',args[0]==='all'?null:args[0]);break;
    case'filter':filter=args[0];render();break;
    case'mobile-menu':mobileOpen=!mobileOpen;render();break;
    case'close-modal':modal.close();break;
    case'create':createWizard();break;
    case'amount':document.querySelector('#donation-amount').value=args[0];updateDonationEstimate();break;
    case'export':await exportReport();break;
    case'switch-reviewer':actor=actor===3?4:3;render();toast(`Now reviewing as ${identities[actor].name}.`);break;
    case'evidence':evidenceForm(args[0],Number(args[1]));break;
    case'inspect':await inspectEvidence(args[0],Number(args[1]));break;
    case'terms':termsModal(args[0]);break;
    case'approve':await run('Recording independent approval…',()=>chain.review(args[0],Number(args[1]),actor,true),'Approval recorded on-chain.');break;
    case'reject':rejectForm(args[0],Number(args[1]));break;
    case'guard':{let reason='';try{await chain.contract(args[0],actor).release.staticCall(Number(args[1]));}catch(err){reason=errorMessage(err);}openModal(reason?'The contract refused this release.':'The release conditions are satisfied.', 'Read-only contract simulation · no tokens moved',`<div class="modal-body"><p>${esc(reason||'The current contract state permits this release.')}</p><p>This check calls the actual contract rules. It does not create a mined transaction or change escrow.</p></div>`);break;}
    case'release':await run('Paying the registered supplier…',()=>chain.release(args[0],Number(args[1]),actor),'Supplier paid. The organiser never received these funds.');break;
    case'claim':await run('Returning your unspent contribution…',()=>chain.claim(args[0],actor),'Refund sent to your wallet.');break;
    case'tx':await transactionModal(args[0]);break;
    case'verify':{const doc=chain.record.evidence[args[0]],valid=doc&&fingerprint(doc)===args[0];document.querySelector('#verify-result').innerHTML=`<div class="verify-result">${valid?'✓ The local evidence matches the fingerprint recorded on-chain.':'Fingerprint mismatch. Do not approve this evidence.'}</div>`;break;}
    case'download-evidence':{const doc=chain.record.evidence[args[0]];if(!doc?.fileData)return;const bytes=Uint8Array.from(atob(doc.fileData),c=>c.charCodeAt(0));download(new Blob([bytes],{type:doc.fileType||'application/octet-stream'}),doc.name);break;}
    case'copy':await navigator.clipboard.writeText(args.join(':'));toast('Copied to clipboard.');break;
    case'add-milestone':readDraft();draft.milestones.push({title:'',supplier:chain.accounts[5],amount:''});wizardRender();break;
    case'remove-milestone':readDraft();draft.milestones.splice(Number(args[0]),1);wizardRender();break;
    case'wizard-back':readDraft();wizardStep--;wizardRender();break;
    case'run-tour':await guidedDemo();break;
    case'examples-confirm':openModal('Rebuild the prepared examples?','This replaces the visible campaign set with twelve prepared scenarios.',`<div class="modal-body"><p>Current campaign records move outside the demo views. New donations, 1% fees, reviews, supplier payments, refunds and reviewer credits are recorded on fresh contracts. This advances the workspace clock by two days. Export records first if needed.</p></div>`,`<div class="modal-footer">${button('Cancel','close-modal','')}${button('Rebuild examples','examples-rebuild','primary','play')}</div>`);break;
    case'examples-rebuild':modal.close();await run('Building twelve recorded campaign scenarios…',()=>ensureDemoScenarios(chain,{force:true}),'Prepared examples rebuilt.');actor=0;go('admin');break;
    case'example-donor':admin.require();actor=Number(args[0]);go('giving');break;
    case'reset':openModal('Reset the sandbox?','This removes the demo data saved in this browser.',`<div class="modal-body"><p style="font-size:12px;color:#899878">Campaigns, uploaded sample evidence and transaction history will be replaced by the twelve prepared scenarios under the current 1% rules. Export your records first if you want to keep a copy.</p></div>`,`<div class="modal-footer">${button('Export report','export','','download')}${button('Cancel','close-modal','')}${button('Reset sandbox','confirm-reset','danger')}</div>`);break;
    case'confirm-reset':localStorage.removeItem(KEY);location.reload();break;
  }}catch(error){console.error(error);if(!document.querySelector('#toast').classList.contains('show'))toast(errorMessage(error),true);}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.campaign-card')){e.preventDefault();e.target.click();}});
document.addEventListener('change',e=>{if(e.target.id==='governance-campaign'){governance.campaign=e.target.value||null;render();}if(e.target.id==='role-select'){try{admin.require();actor=Number(e.target.value);go('overview');toast(`Current account: ${identities[actor].name}.`);}catch(err){render();toast(err.message,true);}}});
document.addEventListener('input',e=>{if(e.target.id==='donation-amount'){updateDonationEstimate();return;}if(e.target.id==='fee-amount'){try{const q=feeScenario(e.target.value);governance.amount=Number(e.target.value);document.querySelector('#fee-quote').innerHTML=governance.quote(q);}catch(err){document.querySelector('#fee-quote').textContent=err.message;}return;}if(e.target.id==='campaign-search'){query=e.target.value;document.querySelector('#campaign-results').innerHTML=filteredCampaigns().map(card).join('')||empty('No campaigns found','Try a different search or filter.');}});
document.addEventListener('submit',async e=>{
  const form=e.target;e.preventDefault();if(busy||sharedUI.syncing)return;
  const error=()=>form.querySelector('#form-error');
  try {
    if(ADMIN_FORMS.has(form.id))admin.require();
    if(await sharedUI.submit(form)||await workflow.submit(form))return;
    if(form.id==='account-form'){
      const i=await run('Preparing your account and wallet…',()=>chain.createAccount(form.elements.name.value,form.elements.kind.value,0),'Account created.');actor=i;modal.close();go('welcome');
    }else if(form.id==='balance-form'){
      await run('Recording your balance adjustment…',()=>chain.setBalance(Number(form.dataset.account),form.elements.value.value),'Available balance updated.');modal.close();
    }else if(form.id==='donation-form'){
      experience.confirmDonation(form.dataset.campaign,form.elements.amount.value,form.elements.source?.value||'wallet');
    }else if(form.id==='donation-confirm-form'){
      await experience.completeDonation();
    }else if(form.id==='organiser-choice-form'){
      admin.require();actor=Number(form.elements.owner.value);modal.close();createWizard();
    }else if(form.id==='campaign-form'){
      readDraft();
      if(wizardStep===0&&(!draft.title.trim()||draft.description.trim().length<20))throw new Error('Add a clear campaign title and a description of at least 20 characters.');
      if(wizardStep<2){wizardStep++;wizardRender();return;}
      const input={...draft,requireVerification:true,conflictsConfirmed:form.elements.confirmed.checked,milestones:draft.milestones.map(m=>({...m,amount:Number(m.amount)}))};
      const address=await run('Deploying your campaign contract…',()=>chain.create(input,draft.owner),'Campaign created. Its funding rules are now fixed.');
      modal.close();go('detail',address);
    }else if(form.id==='evidence-form'){
      const data={...workflow.readEvidence(form),name:form.elements.name.value.trim(),note:form.elements.note.value.trim(),type:'Supporting evidence'};
      if(!data.name||data.note.length<10)throw new Error('Add a document name and at least 10 characters of verification notes.');
      const file=document.querySelector('#evidence-file').files[0];
      if(file){if(file.size>250*1024)throw new Error('Use sample evidence smaller than 250 KB.');const buffer=await file.arrayBuffer();const digest=await crypto.subtle.digest('SHA-256',buffer);data.fileDigest=Array.from(new Uint8Array(digest)).map(b=>b.toString(16).padStart(2,'0')).join('');data.fileData=Array.from(new Uint8Array(buffer)).map(b=>String.fromCharCode(b)).join('');data.fileData=btoa(data.fileData);data.fileType=file.type;data.name=file.name;}
      await run('Recording the evidence fingerprint…',()=>chain.submit(form.dataset.campaign,Number(form.dataset.milestone),data,actor),'Evidence submitted. Both reviewers can now inspect it.');modal.close();
    }else if(form.id==='reject-form'){
      const reason=form.elements.reason.value.trim();if(reason.length<5)throw new Error('Explain the changes needed in at least 5 characters.');
      await run('Recording your review decision…',()=>chain.review(form.dataset.campaign,Number(form.dataset.milestone),actor,false,reason),'Changes requested. Both approvals were reset.');modal.close();
    }
  }catch(err){if(error())error().textContent=errorMessage(err);else toast(errorMessage(err),true);}
});

try {await sharedUI.prepare();
 const prepareExamples=async()=>{const checkpoint=await loadStartupCheckpoint({storage:localStorage,key:KEY,artifacts:startupArtifacts});await chain.init({skipSeed:true,checkpoint});await ensureDemoScenarios(chain);};
 if(!sharedUI.connected&&navigator.locks)await navigator.locks.request('cleargive-local-journal',prepareExamples);
 else if(!sharedUI.connected)await prepareExamples();
 else{await chain.init({skipSeed:true});if(!chain.record.scenarioLibrary?.complete){await sharedUI.beforeMutation();try{await ensureDemoScenarios(chain);await sharedUI.afterMutation();}catch(error){await sharedUI.failedMutation();throw error;}}}
const savedActor=Number(sessionStorage.getItem('cleargive-participant-index')||0);actor=Number.isInteger(savedActor)&&savedActor>=0&&savedActor<identities.length?savedActor:0;render();sharedUI.startPolling();}
catch(error){console.error(error);app.innerHTML=`<div class="boot"><img src="/assets/mark.svg" alt="ClearGive" width="52"><h1>Your workspace couldn’t start.</h1><p>${esc(errorMessage(error))}</p><p>Use a modern browser with local storage enabled. You can export saved data before resetting.</p><div class="buttons"><button class="btn" id="recover-export">Export saved demo data</button><button class="btn danger" id="recover-reset">Reset and retry</button></div></div>`;document.querySelector('#recover-export').onclick=()=>download(new Blob([localStorage.getItem(KEY)||'{}'],{type:'application/json'}),'cleargive-recovery.json');document.querySelector('#recover-reset').onclick=()=>{localStorage.removeItem(KEY);location.reload();};}
